contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // This test takes amount to send and a dummyGasless flag to allow two different call paths.
    // The important part: we send `amount` wei to c via its fallback and then assert the invariant.
    function run(uint amount) public payable {
        // we only model the case where the caller attempts to send exactly some amount of wei
        require(address(this).balance >= amount);

        // observe state before
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // Perform the call to fallback by sending funds; the call is top-level and may revert
        try c.call{value: amount}("") returns (bytes memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // If the call reverted, nothing else guaranteed by contract; assert only for non-revert case
        // General rule: when a non-reverting call sends exactly 10 ether, pastBlockTime becomes block.timestamp;
        // additionally, if block.number % 15 == 0 then c paid out all its balance to msg.sender (this contract),
        // otherwise c's balance after the call is >= balance before the call (it kept funds or received the payment).
        // We express that using observable getters: pastBlockTime and contract balances.
        assert(
            reverted || (
                amount != 10 ether ? true : (
                    // when amount == 10 ether and call did not revert
                    afterPast == block.timestamp && (
                        (block.number % 15 == 0 && afterBal == 0) ||
                        (block.number % 15 != 0 && afterBal >= beforeBal)
                    )
                )
            )
        );
    }

    // Allow this test contract to receive funds when C transfers out on certain blocks
    receive() external payable {}
}

