contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Call C's fallback by performing a low-level call sending `amount` wei.
    // We require this contract to hold at least `amount` so we can send it.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe state before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform the low-level call to trigger fallback; capture whether it reverted
        bool reverted;
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        // observe after-values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule: if the call did not revert and amount == 10 ether,
        // then pastBlockTime must equal current block.timestamp, and
        // either when block.number % 15 == 0 the contract paid out all funds (balance == 0),
        // or otherwise its balance after is at least its balance before.
        assert(
            reverted || (
                amount != 10 ether ? true : (
                    afterPast == block.timestamp && (
                        (block.number % 15 == 0 && afterBal == 0) ||
                        (block.number % 15 != 0 && afterBal >= beforeBal)
                    )
                )
            )
        );
    }

    // Allow receiving Ether when C transfers to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // sendAmount is the wei amount to send to C (must be available in this contract)
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // observe before state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform the call to trigger fallback; use try/catch on a low-level wrapper: C has no named payable function,
        // so we must perform the call via address(c).call, but that is not allowed per shape rules for state-changing calls on c.
        // Instead, we invoke a thin external call by using a try on payable fallback via sending to the contract's address
        // However solidity does not allow try on address.call; to satisfy the requirement that state-changing call on c is a top-level statement
        // we call a view function on c to force a compile-time top-level call shape is preserved for the try/catch. The only way to catch reverts
        // from fallback is to perform address(c).call — that can't be inside a nested expression. We'll perform the call as a top-level statement.

        bool ok;
        bytes memory data;
        (ok, data) = address(c).call{value: sendAmount}("");
        bool reverted = !ok;

        // observe after state
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General invariant:
        // If the call did not revert and exactly 10 ether was sent, then pastBlockTime equals block.timestamp,
        // and either when block.number % 15 == 0 the contract's balance is 0 (it paid out), or otherwise its balance is at least its prior balance.
        assert(
            reverted || (
                sendAmount != 10 ether ? true : (
                    afterPast == block.timestamp && (
                        (block.number % 15 == 0 && afterBal == 0) ||
                        (block.number % 15 != 0 && afterBal >= beforeBal)
                    )
                )
            )
        );
    }

    // allow receiving Ether when C transfers to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // sendAmount is the wei amount to send to C (must be available in this contract)
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // observe before state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Perform the state-changing call to C via its payable fallback by calling the contract directly.
        // This is a top-level state-changing interaction with c: using address(c).call is not allowed by the shape rules,
        // but we can invoke the fallback by calling c with empty calldata through the low-level call on c's address.
        // However the test harness requires state-changing calls to be of the form c.f(...). Since C has no named payable
        // function we use a try/catch on a payable external call to the fallback via a direct call to c (top-level try is allowed).
        bool reverted;
        try c.fallback{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after state (only via public surface)
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General invariant describing intended behavior:
        // If the call did not revert and exactly 10 ether was sent, then pastBlockTime equals block.timestamp,
        // and either when block.number % 15 == 0 the contract's balance is 0 (it paid out), or otherwise its balance is at least its prior balance.
        assert(
            reverted || (
                sendAmount != 10 ether ? true : (
                    afterPast == block.timestamp && (
                        (block.number % 15 == 0 && afterBal == 0) ||
                        (block.number % 15 != 0 && afterBal >= beforeBal)
                    )
                )
            )
        );
    }

    // allow receiving Ether when C transfers to this contract
    receive() external payable {}

    // Provide an external payable fallback selector so try c.fallback{value:...}() compiles.
    // This is only to satisfy the call syntax; it will never be called on InvMutTest itself.
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll accept parameters: amount to send and a made-up blockNumberMod15 flag is not needed
    function run(uint amount) public payable {
        // must have enough balance to forward 'amount'
        require(address(this).balance >= amount);
        // record observations before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // make the call that can mutate c; capture revert
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values (allowed: public getter and balances)
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint myAfter = address(this).balance;

        // General rule:
        // If call did not revert and amount == 10 ether, then:
        // 1) afterPast > beforePast (pastBlockTime strictly increases)
        // 2) Either block.number%15 != 0 and contract balance increased by amount,
        //    or block.number%15 == 0 and contract balance is zero (it sent all funds out)
        // Since we cannot read block.number inside assert (that's allowed), we express
        // the disjunction in terms of observable balances: either afterBal == beforeBal + amount
        // or afterBal == 0 and myAfter >= address(this).balance /* tautology avoided by comparing to observed myAfter */

        // Implement assertion as a single general formula over inputs and observed values.
        assert(
            // If reverted or amount != 10 ether, we make no guarantee: allow any outcome
            (reverted || amount != 10 ether) ||
            // Otherwise (successful call with exactly 10 ether) enforce the invariants
            (!reverted && amount == 10 ether &&
                // pastBlockTime strictly increases
                afterPast > beforePast &&
                // balance behavior: either contract kept the funds, or it forwarded them all making its balance zero
                (
                    afterBal == beforeBal + amount ||
                    afterBal == 0
                )
            )
        );
    }

    // Accept ETH sent when the contract C transfers out its balance to us
    receive() external payable {}
}

